import{runPlan}from'./path-trials-layout.js';
const TRIALS={boulders:'boulder passage',moving:'moving platforms',thorns:'thorn gaps',wind:'wind shelters',crystals:'crystal barrier',bonus:'optional gold ledges'},RIVALS={ram:'Rumblebud',seed:'Brambleguard',spore:'Mistcap'};
const SCENES=[
 [['Sheltered Spring','A thirsty valley waits for its water to return.','The spring trail carries water and supplies again.'],['Ruined Aqueduct','The old watercourse needs a working crossing.','The broken watercourse has a safe passage again.'],['Split-Oak Lookout','The lookout has lost its signals.','The lookout can guide travellers again.'],['Fractured Passage','Supplies lie beyond the fractured stone.','The passage is clear and its supplies are secured.'],['Wind Sanctuary','The sanctuary waits beyond the final mechanisms.','The sanctuary approach is restored.']],
 [['Cloudroot Approach','A hillside trail leads toward the cloud terraces.','The first cloud terrace is ready for travellers.'],['Sunlit Watercourse','Follow the water toward the high arches.','The watercourse has a working passage.'],['Bellwind Lookout','The lookout bells have fallen silent.','The lookout can send its messages again.'],['Hanging Gardens','The garden stores need a careful delivery.','The gardens have their supplies again.'],['Crown of Arches','Restore the approach beneath the highest arches.','The crown approach is open and supplied.']],
 [['Basalt Threshold','A sheltered trail enters the dark stone valley.','The threshold offers a safe approach.'],['Glasswater Crossing','Follow the stream between fractured crystals.','The crossing is ready beneath the crystal walls.'],['Echo Spire','The spire needs its messages reconnected.','The spire can answer the valley again.'],['Hidden Reservoir','Recover supplies beside the old reservoir.','The reservoir trail is repaired and supplied.'],['Stormglass Refuge','The last mechanisms protect a quiet refuge.','The refuge approach is restored.']]
];
export function routePreview(e,chapter,side){const p=runPlan(e,chapter,side);const names={quiet:'quiet approach',trial:TRIALS[p.trial],rival:RIVALS[p.rival],traverse:{rocks:'rock crossing',plants:'plant gaps',steps:'terrace climb'}[p.kinds[p.sequence?.indexOf('traverse')]]};return{trial:p.trial,rival:p.rival,sequence:p.sequence?.slice(),text:p.sequence?p.sequence.slice(1).map(k=>names[k]).join(' → '):`${TRIALS[p.trial]} · ${RIVALS[p.rival]}`};}
export function forkHint(e,chapter){return e.pacingVersion>=1?`Left: ${TRIALS[runPlan(e,chapter,'left').trial]} · Right: ${TRIALS[runPlan(e,chapter,'right').trial]}`:'Choose a path with the arrows or joystick.';}
export function sceneBeat(e,chapter){const s=SCENES[e.area]?.[chapter]||SCENES[0][0],restored=(e.completed||[]).filter(r=>Math.floor(r.index/4)===chapter).length;return{title:s[0],restored,text:restored===4?s[2]:s[1],discovered:(e.travel?.collected||[]).some(id=>id===`${e.id}:travel:${chapter*4}:discovery:0`)};}
